// @prog returns the list of largest elements in descending order.
@prog = (l out)
  & @take ~ (l (4 out))

@take = ((?((@take_nil @take_cons) (pl (n out))) pl) (n out))

@take_nil = (* (n out))
  & n ~ *
  & out ~ (0 *)

@take_cons = (* ((h t) (n out)))
  & n ~ ?((@take_stop @take_more) (h (t out)))

@take_stop = (h (t out))
  & h ~ out
  & t ~ *

@take_more = (n (h (t out)))
  & @take ~ (t (n rest))
  & out ~ (1 (h rest))
